        raise SubtitleParseError("Không có nội dung phụ đề để tạo chunk.")

    base_meta = dict(extra_metadata or {})
    chunks: list[SubtitleChunk] = []
    buffer: list[Cue] = []

    def flush() -> None:
        if not buffer:
