    for cue in cues:
        buffer.append(cue)
        duration = (buffer[-1].end_ms - buffer[0].start_ms) / 1000
        chars = sum(len(c.text) for c in buffer)
        if duration >= max_seconds or chars >= MAX_CHUNK_CHARS:
